#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    int getMaxLen(vector<int>& nums) {
        int n = nums.size();
        int pos = 0, neg = 0, result = 0;

        for (int i = 0; i < n; ++i) {
            if (nums[i] > 0) {
                pos++;
                neg = (neg == 0) ? 0 : neg + 1;
            } else if (nums[i] < 0) {
                int temp = pos;
                pos = (neg == 0) ? 0 : neg + 1;
                neg = temp + 1;
            } else {
                pos = neg = 0;
            }

            result = max(result, pos);
        }

        return result;
    }
};
